            "id": "s003",
            "kind": "call",
            "fn": "save"
          }
        ],
        "else": []
      }
    ],
    "save": [
      {
        "id": "s005",
        "kind": "effect",
        "op": "write",
        "resource": "/synthetic/phase7/permission_split/saffron/out",
        "value": "saffron"
      },
      {
        "id": "s007",
        "kind": "repeat",
        "count": 2,
        "body": [
          {
            "id": "s006",
